import yaml,glob,re,fnmatch
T={}
for p in glob.glob('.tickets/*.md'):
    s=open(p).read()
    try: d=yaml.safe_load(s.split('\n---',1)[0].lstrip('-\n'))
    except: continue
    if d.get('wbs_id'): T[d['wbs_id']]=d
cand=['W2-105','W2-90b','W2-91','W2-33','W2-60a','W2-04','W2-61h','W2-94','W2-104','W2-115','W2-109','W2-82','W2-56','W2-09','W2-12','W2-17','W2-18','W2-19','W2-23','W2-31','W2-34','W2-83b','W2-60b']
run=['W2-92','W2-13','W2-81','W2-11']
def rx(p): return re.compile('^'+re.escape(p).replace(r'\*\*','.*').replace(r'\*','[^/]*')+'$')
def ov(a,b):
    out=[]
    for x in a:
        for y in b:
            # overlap if either pattern could match the other's literal prefix
            px=x.split('*')[0]; py=y.split('*')[0]
            if px.startswith(py) or py.startswith(px):
                if rx(x).match(y.replace('**','a/b').replace('*','a')) or rx(y).match(x.replace('**','a/b').replace('*','a')) or x==y: out.append(f"{x}~{y}")
    return out
for c in cand:
    d=T.get(c); 
    if not d: print(c,'missing'); continue
    P=d.get('allowed_paths') or []
    hits=[]
    for o in run+cand:
        if o==c or o not in T: continue
        h=ov(P,T[o].get('allowed_paths') or [])
        h=[x for x in h if not x.startswith('tests/acceptance/'+c)]
        if h: hits.append(f"{o}:{h[:2]}")
    print(f"{c} [{d.get('role')},{d.get('profile')}] {d.get('title','')[:70]}\n   paths={P[:6]}{'...' if len(P)>6 else ''}\n   overlaps={hits}")
EOF
